using System;using System.Linq;using System.Reflection;using System.Collections.Generic;
class MappingTest{
 static Type b=typeof(Bridge);static object Call(string n,params object[] args){return b.GetMethod(n,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static Dictionary<string,object> Device(string id,string product,int value){return new Dictionary<string,object>{{"id",id},{"productId",product},{"axes",new Dictionary<string,object>{{"X",value}}}};}
 static void Main(){var ds=new List<Dictionary<string,object>>{Device("wheel","p1",32768),Device("pedals","p2",65535)};var spec=new Dictionary<string,object>{{"deviceId","pedals"},{"productId","p2"},{"axis","X"},{"min",0},{"max",65535},{"invert",true}};Check((double)Call("Axis",ds,spec,false)==0,"Inverted separate pedal");spec["deviceId"]="old-port";spec["invert"]=false;Check((double)Call("Axis",ds,spec,false)==1,"Unique product fallback");ds.Add(Device("pedals2","p2",0));Check(Call("Axis",ds,spec,false)==null,"Ambiguous identical device must not be guessed");spec["deviceId"]="wheel";Check(Math.Abs((double)Call("Axis",ds,spec,true))<.001,"Steering center");spec["max"]=1;try{Call("Validate",new Dictionary<string,object>{{"inputs",new Dictionary<string,object>{{"handbrakeInputs",new object[]{spec}}}}});throw new Exception("Invalid dual handbrake calibration accepted");}catch(TargetInvocationException e){Check(e.InnerException is ArgumentException,"Mapping rejected for expected reason");}Console.WriteLine("Bridge mapping fixtures OK");}
}
